    int is_nmap = 0;
    int is_version = 0;
    int is_help = 0;
    int show_short_help = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--echo") == 0) is_echo = 1;
        else if (strcmp(argv[i], "--nmap") == 0) is_nmap = 1;
        else if (strcmp(argv[i], "-V") == 0) is_version = 1;
        else if (strcmp(argv[i], "--help") == 0) is_help = 1;
        else if (strcmp(argv[i], "-h") == 0) show_short_help = 1;
        else if (strcmp(argv[i], "--seed") == 0 && i + 1 < argc) config.seed = strtoull(argv[++i], NULL, 10);
        else if (strcmp(argv[i], "--rate") == 0 && i + 1 < argc) config.rate = strtoull(argv[++i], NULL, 10);
        else if (strncmp(argv[i], "--rate=", 7) == 0) config.rate = strtoull(argv[i] + 7, NULL, 10);
        else if (strcmp(argv[i], "--ports") == 0 && i + 1 < argc) parse_ports(&config, argv[++i]);
        else if (strncmp(argv[i], "-p", 2) == 0) {
            if (strlen(argv[i]) > 2) parse_ports(&config, argv[i] + 2);
            else if (i + 1 < argc) parse_ports(&config, argv[++i]);
        }
        else if (strcmp(argv[i], "--banners") == 0) config.banners = 1;
        else if (strcmp(argv[i], "--source-ip") == 0 || strcmp(argv[i], "--adapter-ip") == 0) {
            if (i + 1 < argc) config.adapter_ip = argv[++i];
        }
        else if (strcmp(argv[i], "--source-port") == 0 || strcmp(argv[i], "--adapter-port") == 0) {
            if (i + 1 < argc) config.adapter_port = atoi(argv[++i]);
        }
        else if (strcmp(argv[i], "--adapter-mac") == 0) {
            if (i + 1 < argc) config.adapter_mac = argv[++i];
        }
        else if (strcmp(argv[i], "--router-mac") == 0) {
            if (i + 1 < argc) config.router_mac = argv[++i];
        }
        else if (strcmp(argv[i], "--output-format") == 0) {
            if (i + 1 < argc) config.output_format = argv[++i];
        }
        else if (strcmp(argv[i], "--output-filename") == 0 || strcmp(argv[i], "--output-file") == 0) {
            if (i + 1 < argc) config.output_filename = argv[++i];
        }
        else if (strcmp(argv[i], "--shard") == 0 && i + 1 < argc) config.shard = argv[++i];
        else if (argv[i][0] != '-') add_ip_range(&config, argv[i]);
    }

    if (is_version) {
        print_version();
        return 1;
    }
    if (is_nmap) {
        print_nmap_help();
        return 1;
    }
    if (is_help) {
        print_help();
        return 1;
    }
    if (show_short_help) {
        print_short_help();
        return 1;
    }

