        fprintf(stderr, "[-] FAIL: failed to load libpcap shared library\n"
                        "    [hint]: you must install libpcap or WinPcap\n");

        if (config.seed == 0) {
            int fd = open("/dev/urandom", O_RDONLY);
            if (fd >= 0) {
                read(fd, &config.seed, sizeof(config.seed));
                close(fd);
            } else {
                config.seed = time(NULL);
            }
        }

        printf("seed = %llu\n", (unsigned long long)config.seed);
        printf("rate = %-10llu\n", (unsigned long long)config.rate);
        printf("shard = %s\n", config.shard);
        if (config.banners) printf("banners = true\n");
        printf("nocapture = servername\n");
        printf("nocapture = servername\n\n");

        if (config.output_filename) printf("output-filename = %s\n", config.output_filename);
        if (config.output_format) printf("output-format = %s\n", config.output_format);
        if (config.output_filename || config.output_format) printf("\n");
        else printf("\n");

        if (config.adapter_ip) printf("adapter-ip = %s\n", config.adapter_ip);
        if (config.adapter_port) printf("adapter-port = %d\n", config.adapter_port);
        if (config.adapter_mac) printf("adapter-mac = %s\n", config.adapter_mac);
        if (config.router_mac) printf("router-mac = %s\n", config.router_mac);

        printf("# TARGET SELECTION (IP, PORTS, EXCLUDES)\n");
        printf("ports = ");
        int first_port = 1;
        for (int p = 0; p < 4; p++) {
            range_list_sort_and_merge(&config.ports[p]);
            for (size_t j = 0; j < config.ports[p].count; j++) {
                if (!first_port) printf(",");
                if (p == 1) printf("U:");
                else if (p == 2) printf("S:");
                else if (p == 3) printf("I:");
                if (config.ports[p].ranges[j].begin == config.ports[p].ranges[j].end)
                    printf("%u", config.ports[p].ranges[j].begin);
                else
                    printf("%u-%u", config.ports[p].ranges[j].begin, config.ports[p].ranges[j].end);
                first_port = 0;
            }
        }
        printf("\n");
        if (config.num_ip_ranges > 0) {
            qsort(config.ip_ranges, config.num_ip_ranges, sizeof(char *), compare_strings);
            for (size_t i = 0; i < config.num_ip_ranges; i++) {
                printf("range = %s\n", config.ip_ranges[i]);
            }
        }
        return 0;
    }

    fprintf(stderr, "[-] FAIL: failed to load libpcap shared library\n"
                    "    [hint]: you must install libpcap or WinPcap\n");
    return 1;
}
