void range_list_add(RangeList *list, uint32_t begin, uint32_t end) {
    if (list->count >= list->capacity) {
        list->capacity = list->capacity ? list->capacity * 2 : 16;
        list->ranges = realloc(list->ranges, list->capacity * sizeof(Range));
