    size_t capacity;
} RangeList;

void range_list_add(RangeList *list, uint32_t begin, uint32_t end) {
    if (list->count >= list->capacity) {
        list->capacity = list->capacity ? list->capacity * 2 : 16;
        list->ranges = realloc(list->ranges, list->capacity * sizeof(Range));
    }
    list->ranges[list->count].begin = begin;
    list->ranges[list->count].end = end;
    list->count++;
}

int compare_ranges(const void *a, const void *b) {
    Range *ra = (Range *)a;
    Range *rb = (Range *)b;
    if (ra->begin < rb->begin) return -1;
    if (ra->begin > rb->begin) return 1;
    if (ra->end < rb->end) return -1;
    if (ra->end > rb->end) return 1;
    return 0;
}

void range_list_sort_and_merge(RangeList *list) {
    if (list->count == 0) return;
    qsort(list->ranges, list->count, sizeof(Range), compare_ranges);
    size_t new_count = 1;
    for (size_t i = 1; i < list->count; i++) {
        if (list->ranges[i].begin <= list->ranges[new_count - 1].end + 1) {
            if (list->ranges[i].end > list->ranges[new_count - 1].end) {
                list->ranges[new_count - 1].end = list->ranges[i].end;
            }
        } else {
            list->ranges[new_count++] = list->ranges[i];
        }
    }
    list->count = new_count;
}

typedef struct {
    uint64_t seed;
    uint64_t rate;
    char *shard;
    int banners;
    char *output_filename;
    char *output_format;
    char *adapter_ip;
    int adapter_port;
    char *adapter_mac;
    char *router_mac;
    RangeList ports[4]; // TCP, UDP, SCTP, IP
    char **ip_ranges;
    size_t num_ip_ranges;
} Config;

void parse_ports(Config *config, const char *s) {
    int proto = 0; // TCP
    const char *p = s;
    while (*p) {
        while (*p && (isspace(*p) || *p == ',')) p++;
        if (!*p) break;
        if (strncmp(p, "T:", 2) == 0) { proto = 0; p += 2; }
        else if (strncmp(p, "U:", 2) == 0) { proto = 1; p += 2; }
        else if (strncmp(p, "S:", 2) == 0) { proto = 2; p += 2; }
        else if (strncmp(p, "I:", 2) == 0) { proto = 3; p += 2; }

        if (!isdigit(*p)) { p++; continue; }

        char *endptr;
        uint32_t begin = strtoul(p, &endptr, 10);
        p = endptr;
        uint32_t end = begin;
        if (*p == '-') {
            p++;
            end = strtoul(p, &endptr, 10);
            p = endptr;
        }
        range_list_add(&config->ports[proto], begin, end);
    }
}

void add_ip_range(Config *config, const char *s) {
    config->ip_ranges = realloc(config->ip_ranges, (config->num_ip_ranges + 1) * sizeof(char *));
    config->ip_ranges[config->num_ip_ranges++] = strdup(s);
}

int compare_strings(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

