           "your first config file, or see a list of parameters you didn't know\n"
           "about. I suggest you try it now:\n"
           "\n"
           "    masscan -p1234 --echo\n");
}

void print_short_help() {
    printf("usage: masscan [options] [<IP|RANGE>... -pPORT[,PORT...]]\n"
