int main(int argc, char *argv[]) {
    Config config = {0};
    config.rate = 100;
    config.shard = "1/1";
    int is_echo = 0;
    int is_nmap = 0;
    int is_version = 0;
    int is_help = 0;
    int show_short_help = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--echo") == 0) is_echo = 1;
        else if (strcmp(argv[i], "--nmap") == 0) is_nmap = 1;
        else if (strcmp(argv[i], "-V") == 0) is_version = 1;
        else if (strcmp(argv[i], "--help") == 0) is_help = 1;
        else if (strcmp(argv[i], "-h") == 0) show_short_help = 1;
        else if (strcmp(argv[i], "--seed") == 0 && i + 1 < argc) config.seed = strtoull(argv[++i], NULL, 10);
        else if (strcmp(argv[i], "--rate") == 0 && i + 1 < argc) config.rate = strtoull(argv[++i], NULL, 10);
        else if (strncmp(argv[i], "--rate=", 7) == 0) config.rate = strtoull(argv[i] + 7, NULL, 10);
        else if (strcmp(argv[i], "--ports") == 0 && i + 1 < argc) parse_ports(&config, argv[++i]);
        else if (strncmp(argv[i], "-p", 2) == 0) {
            if (strlen(argv[i]) > 2) parse_ports(&config, argv[i] + 2);
            else if (i + 1 < argc) parse_ports(&config, argv[++i]);
        }
        else if (strcmp(argv[i], "--banners") == 0) config.banners = 1;
        else if (strcmp(argv[i], "--source-ip") == 0 || strcmp(argv[i], "--adapter-ip") == 0) {
            if (i + 1 < argc) config.adapter_ip = argv[++i];
        }
        else if (strcmp(argv[i], "--source-port") == 0 || strcmp(argv[i], "--adapter-port") == 0) {
            if (i + 1 < argc) config.adapter_port = atoi(argv[++i]);
        }
        else if (strcmp(argv[i], "--adapter-mac") == 0) {
            if (i + 1 < argc) config.adapter_mac = argv[++i];
        }
        else if (strcmp(argv[i], "--router-mac") == 0) {
            if (i + 1 < argc) config.router_mac = argv[++i];
        }
        else if (strcmp(argv[i], "--output-format") == 0) {
            if (i + 1 < argc) config.output_format = argv[++i];
        }
        else if (strcmp(argv[i], "--output-filename") == 0 || strcmp(argv[i], "--output-file") == 0 || strncmp(argv[i], "-o", 2) == 0) {
             // Handle output flags like -oX, -oJ, etc.
             if (strncmp(argv[i], "-o", 2) == 0 && strlen(argv[i]) == 3) {
                 char fmt = argv[i][2];
                 if (fmt == 'X') config.output_format = "xml";
                 else if (fmt == 'J') config.output_format = "json";
                 else if (fmt == 'G') config.output_format = "grepable";
                 else if (fmt == 'B') config.output_format = "binary";
                 else if (fmt == 'L') config.output_format = "list";
                 if (i + 1 < argc) config.output_filename = argv[++i];
             } else if (strcmp(argv[i], "--output-filename") == 0 || strcmp(argv[i], "--output-file") == 0) {
                 if (i + 1 < argc) config.output_filename = argv[++i];
             }
        }
        else if (strcmp(argv[i], "--shard") == 0 && i + 1 < argc) config.shard = argv[++i];
        else if (argv[i][0] != '-') add_ip_range(&config, argv[i]);
    }

    if (is_version) {
        print_version();
        return 1;
    }
    if (is_nmap) {
        print_nmap_help();
        return 1;
    }
    if (is_help) {
        print_help();
        return 1;
    }
    if (show_short_help) {
        print_short_help();
        return 1;
    }

    if (is_echo) {
        fprintf(stderr, "[-] FAIL: failed to load libpcap shared library\n"
                        "    [hint]: you must install libpcap or WinPcap\n");

        if (config.seed == 0) {
            int fd = open("/dev/urandom", O_RDONLY);
            if (fd >= 0) {
                read(fd, &config.seed, sizeof(config.seed));
                close(fd);
            } else {
                config.seed = time(NULL);
            }
        }

        printf("seed = %llu\n", (unsigned long long)config.seed);
        printf("rate = %-10llu\n", (unsigned long long)config.rate);
        printf("shard = %s\n", config.shard);
        if (config.banners) printf("banners = true\n");
        printf("nocapture = servername\n");
        printf("nocapture = servername\n\n");

        if (config.output_filename) printf("output-filename = %s\n", config.output_filename);
        if (config.output_format) printf("output-format = %s\n", config.output_format);
        if (config.output_filename || config.output_format) printf("\n");
        else printf("\n");

        if (config.adapter_ip) printf("adapter-ip = %s\n", config.adapter_ip);
        if (config.adapter_port) printf("adapter-port = %d\n", config.adapter_port);
        if (config.adapter_mac) printf("adapter-mac = %s\n", config.adapter_mac);
        if (config.router_mac) printf("router-mac = %s\n", config.router_mac);

        printf("# TARGET SELECTION (IP, PORTS, EXCLUDES)\n");
        printf("ports = ");
        int first_port = 1;
        for (int p = 0; p < 4; p++) {
            range_list_sort_and_merge(&config.ports[p]);
            for (size_t j = 0; j < config.ports[p].count; j++) {
                if (!first_port) printf(",");
                if (p == 1) printf("U:");
                else if (p == 2) printf("S:");
                else if (p == 3) printf("I:");
                if (config.ports[p].ranges[j].begin == config.ports[p].ranges[j].end)
                    printf("%u", config.ports[p].ranges[j].begin);
                else
                    printf("%u-%u", config.ports[p].ranges[j].begin, config.ports[p].ranges[j].end);
                first_port = 0;
            }
        }
        printf("\n");
        if (config.num_ip_ranges > 0) {
            qsort(config.ip_ranges, config.num_ip_ranges, sizeof(char *), compare_strings);
            for (size_t i = 0; i < config.num_ip_ranges; i++) {
                printf("range = %s\n", config.ip_ranges[i]);
            }
        }
        return 0;
    }

    fprintf(stderr, "[-] FAIL: failed to load libpcap shared library\n"
                    "    [hint]: you must install libpcap or WinPcap\n");
    return 1;
}
